type AgentLog={event_id:string;timestamp:string;event_type:string;event_name:string;test_run_id:string|null;severity:string;action_id:string|null;trace_id:string|null;span_id:string|null;agent_id:string;tool_name:string|null;jev_recommendation:string|null;jev_status:string|null;aura_decision:string|null;risk_level:string|null;policy_id:string|null;reason_codes:string[];execution_status:string|null;duration_ms:number|null;detail:Record<string,unknown>;timeline?:AgentLog[]};
