 const load=useCallback(async()=>{setLoading(true);try{setError('');const q=new URLSearchParams({limit:'50',offset:String(offset),time_range:range,sort});for(const [key,value] of [['severity',severity],['decision',decision],['tool_name',tool],['agent_id',agent],['event_type',kind],['execution_status',execution],['search',search]])if(value)q.set(key,value);if(testAccess)q.set('test_run_id',testAccess.testRunId);const r=await fetch(`${API}/agent-logs?${q}`,{headers:testAccess?{'X-AURA-Test-Token':testAccess.token}:{}});if(!r.ok)throw new Error('Could not load agent event logs.');const data=await r.json();setItems(data.items);setTotal(data.total)}catch(e){setError(e instanceof Error?e.message:'Could not load event logs')}finally{setLoading(false)}},[offset,range,sort,severity,decision,tool,agent,kind,execution,search,testAccess]);
