 {selected&&<div className="timeline-backdrop" role="presentation" onClick={()=>setSelected(null)}><section className="timeline-drawer log-drawer" role="dialog" aria-modal="true" aria-label="Agent event detail" onClick={e=>e.stopPropagation()}><div className="panel-heading"><div><h2>{selected.event_name}</h2><p>{selected.event_id}</p></div><button className="icon-button" aria-label="Close event detail" onClick={()=>setSelected(null)}>×</button></div><div className="timeline-meta"><span>Severity<b>{selected.severity}</b></span><span>Timestamp<b>{new Date(selected.timestamp).toLocaleString()}</b></span><span>Action ID<b>{selected.action_id||'Unavailable'}</b></span><span>Trace ID<b>{selected.trace_id||'Unavailable'}</b></span><span>Agent / Tool<b>{selected.agent_id} · {selected.tool_name||'Unavailable'}</b></span><span>JEV / AURA<b>{selected.jev_recommendation||'Unavailable'} / {selected.aura_decision||'Unavailable'}</b></span><span>Execution<b>{selected.execution_status||'Unavailable'}</b></span><span>Reason codes<b>{selected.reason_codes.join(', ')||'Unavailable'}</b></span></div><h3 className="event-timeline-title">Trace timeline</h3><div className="timeline-list">{selected.timeline?.length?selected.timeline.map((item,index)=><div className="timeline-entry" key={`${item.event_id}-${index}`}><i/><div><b>{item.event_name}</b><small>{new Date(item.timestamp).toLocaleString()} · {item.severity}</small><span className="log-decision-line">JEV {item.jev_recommendation||'—'} · AURA {item.aura_decision||'—'} · Execution {item.execution_status||'—'}</span></div></div>):<p className="monitor-empty">No correlated events were stored for this trace.</p>}</div><details className="raw-event"><summary>Raw Event / Structured Data</summary><pre>{JSON.stringify(selected,null,2)}</pre></details></section></div>}
