type MonitoringSummary={total_actions:number;blocked_actions:number;blocked_percent:number|null;pending_approvals:number;average_decision_latency_ms:number|null;p95_decision_latency_ms:number|null;latency_sample_count:number;authentication_enabled:boolean;decisions:{allowed:number;blocked:number;approval_required:number}};
