  <div className="notice"><div><span className="notice-icon"><ShieldCheck size={16}/></span><span><b>Persisted action monitoring</b><small>Data is read from AURA tool traces and audit records. Dashboard refreshes every 15 seconds.</small></span></div><div className="monitor-actions"><select aria-label="Monitoring time range" value={range} onChange={e=>{setOffset(0);setRange(e.target.value)}}><option value="1h">Last hour</option><option value="24h">Last 24 hours</option><option value="7d">Last 7 days</option><option value="all">All time</option></select><a className="outline-button" href={exportHref}>Export CSV</a></div></div>
